public int bsearch(int[] arr, int el){
int low=0;
int high=arr.length;
int mid=0;
while(low < high){
mid=(low+high) / 2 ;
if(arr[mid] == el ){
return mid; // position index
}else if (arr[mid] < el ){
low=mid+1;
//we checked middle already
}else{
high = mid-1;
//we checked middle already
}
}
//if we came here
//it means we couldn’t find it
return -1;
}

